    [2040] = { "Asalto subterráneo", "Recupera la Dentrituradora goblin de Las Minas de la Muerte y devuélveselo a Shoni la Shilenshiosha, en Ventormenta." },
    [2198] = { "El collar hecho añicos", "Busca al creador del collar hecho añicos y descubre para qué sirve." },
    [2199] = { "Esa información tiene un precio", "Lleva cinco lingotes de plata a Talvash del Kissel a Forjaz." },
    [2200] = { "El regreso a Uldaman", "Busca pistas sobre el paradero del collar de Talvash en Uldaman. Dijo que un paladín muerto fue su último dueño." },
    [2201] = { "Encuentra las gemas", "Encuentra el rubí, el zafiro y el topacio que están desperdigados por Uldaman. Cuando los tengas, contacta con Talvash del Kissel mediante la ampolla de adivinación que él te dio.\n\nA través del diario, sabes que...\n*El rubí está escondido en una zona de Forjatiniebla con barricadas.\n*El topacio permanece oculto en una urna en una de las zonas de los troggs, cerca de algunos enanos de la Alianza.\n\n*El zafiro obra en poder de Grimlok, el líder de los troggs, según él mismo afirma." },
    [2202] = { "Componentes de Uldaman", "Llévale 12 setas magenta a Jarkal Musgofusión en Kargath." },
    [2203] = { "Componentes de Tierras Inhóspitas II", "Usa las vasijas de taumaturgia vacías con los dragones guardianes agostados de las Tierras Inhóspitas. Cuando las hayas llenado, llévaselas a Jarkal Musgofusión en Kargath." },
    [2204] = { "Restaurar el collar", "Obtén una fuente de energía del ensamblaje más poderoso que encuentres en Uldaman, y entrégasela a Talvash del Kissel en Forjaz." },
    [2240] = { "La cámara oculta", "Lee el diario de Baelog, inspecciona la cámara oculta y ve a informar al prospector Pico Tormenta." },
    [2258] = { "Componentes de Tierras Inhóspitas", "Llévale 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de roca a Jarkal Musgofusión en Kargath, en las Tierras Inhóspitas." },
    [2278] = { "Los discos de platino", "Habla con el vigía de piedra y descubre qué conocimiento antiguo alberga. Cuando hayas adquirido el conocimiento que te ofrece, activa los Discos de Norgannon." },
    [2279] = { "Los discos de platino", "Lleva la reproducción en miniatura de los Discos de Norgannon a la Liga de Expedicionarios de Forjaz." },
    [2280] = { "Los discos de platino", "Lleva la reproducción en miniatura de los Discos de Norgannon a alguien que esté muy interesado." },
    [2283] = { "La recuperación del collar", "Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar. Puede que el collar esté estropeado." },
    [2284] = { "La recuperación del collar, 2ª parte", "Busca pistas sobre el paradero de las gemas en las profundidades de Uldaman." },
    [2318] = { "La traducción del diario", "Encuentra a alguien que pueda traducir el diario del paladín. El lugar más cercano en el que podrás encontrar a alguien es Kargath, en las Tierras Inhóspitas." },
    [2338] = { "La traducción del diario", "Préstale el collar a Jarkal. A cambio, te traducirá el diario." },
    [2339] = { "Encuentra las gemas y la fuente de alimentación", "Recupera las 3 gemas y una fuente de energía para el collar de Uldaman y llévalo todo a Jarkal Musgofusión en Kargath. Jarkal cree que es posible que la fuente de energía más poderosa se halle en un ensamblaje de Uldaman.\n\nPor el diario sabes...\n* Que han ocultado el rubí en una zona cerrada con barricadas en Forjatiniebla.\n* Que el topacio se ha ocultado en una urna en un área trogg, cerca de los enanos de la Alianza.\n* Que Grimlok, el jefe trogg, se ha quedado con el zafiro." },
    [2340] = { "Entregar las gemas", "Entrégale el collar y la gema recuperados a Dran Droffers en Orgrimmar." },
    [2341] = { "La recuperación del collar, 3ª parte", "Habla con Jarkal Musgofusión en Kargath." },
    [2342] = { "Los tesoros reclamados", "Coge el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas." },
    [2361] = { "Restaurar el collar" },
    [2398] = { "Los enanos desaparecidos", "Encuentra a Baelog en Uldaman." },
