    [2768] = { "Vara divinomática", "Lleva la vara divinomática al ingeniero jefe Pasaquillas en Gadgetzan." },
    [2770] = { "Gahz'rilla", "Llévale la escama electrificada de Gahz'rilla a Wizzle Pernolatón, que está en El Desierto de Sal." },
    [2841] = { "Las guerras de la plataforma", "Consigue la combinación de la caja fuerte de Termochufe en Gnomeregan y lleva los planos de la plataforma a Nogg a Orgrimmar.|n" },
    [2842] = { "Scooty, ingeniero jefe", "Habla con Scooty en Bahía del Botín." },
    [2843] = { "¡Gnomer-yaaaaa!", "Espera a que Scooty calibre el transpondedor goblin." },
    [2846] = { "Tiara de las profundidades", "Lleva la tiara de las profundidades a Tabetha en el Marjal Revolcafango." },
    [2865] = { "Caparazones de escarabajo", "Lleva 5 caparazones de escarabajo sin rajar a Tran'rek en Gadgetzan." },
    [2904] = { "Un buen lío", "Acompaña a Kernobee a La Rampa del Engranaje y luego ve a ver a Scooty a Bahía del Botín." },
    [2922] = { "¡Salva el cerebro de Tecnobot!", "Lleva el procesador central de memoria del Tecnobot al maestro manitas Sobrechispa a Forjaz." },
    [2924] = { "Esencias artificiales", "Lleva 12 esencias artificiales a Klockmort Palmalicate a Forjaz." },
    [2926] = { "Gnogaine", "Usa la ampolla de plomo con invasores o saqueadores radiactivos para recoger restos radiactivos. Cuando esté llena, llévasela a Ozzie Voltiflop a Kharanos." },
    [2928] = { "Excavadoras gyroagujereamáticas", "Lleva veinticuatro entrañas robomecánicas a Shoni en Ventormenta." },
    [2929] = { "La gran traición", "Ve a Gnomeregan y mata al mekigeniero Termochufe. Ve a ver al Manitas Mayor Mekkatorque cuando hayas terminado." },
    [2930] = { "Rescatar los datos", "Lleva una tarjeta perforada prismática al maestro mecánico Funditubo a Forjaz." },
    [2933] = { "Botellas de veneno", "Lleva una botella de veneno a algún boticario de Molino Tarren." },
    [2934] = { "Glándula de veneno intacta", "Lleva una glándula de veneno intacta al boticario Lydon de Molino Tarren." },
    [2935] = { "Consulta al maestro Gadrin", "Habla con el maestro Gadrin en el Poblado Sen'jin." },
    [2936] = { "Diosa araña", "Lee el nombre de la diosa araña de los Secacorteza en la tablilla de Theka y vuelve a ver al maestro Gadrin." },
    [2937] = { "Invocar a Shadra", "Derrota a Shadra en el altar de Shadra'Alor y lleva su veneno al boticario Lydon de Molino Tarren." },
    [2938] = { "Veneno para Entrañas", "Lleva el paquete al maestro boticario Faranell a Entrañas." },
    [2945] = { "Un anillo sucio", "Encuentra la manera de limpiar el anillo sucio." },
    [2946] = { "A ver qué pasa", "Lleva los discos de platino en miniatura a las puertas de Uldum, en Tanaris. Busca pistas sobre la conexión entre discos y puertas." },
    [2947] = { "La devolución del anillo", "Puedes quedarte el anillo o buscar a quien realizó los grabados de la parte interior." },
    [2948] = { "Mejora gnómica", "Lleva tu anillo de oro luminoso, una barra de plata, una ágata musgosa y 30 monedas de plata a Talvash del Kissel a Forjaz." },
    [2949] = { "La devolución del anillo", "Puedes quedarte el anillo o buscar a quien realizó los grabados de la parte interior." },
    [2950] = { "Nogg mejora el anillo", "Lleva tu anillo de oro luminoso, una barra de plata, una ágata musgosa y 30 monedas de plata a Nogg a Orgrimmar." },
    [2951] = { "¡El Destellamatic 5200!", "Inserta un objeto con mugre incrustada en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano." },
    [2952] = { "¡El Destellamatic 5200!" },
    [2953] = { "El Destellamatic en acción" },
    [2954] = { "El vigía de piedra", "Averigua qué quiere el vigía de piedra de Norgannon y después interactúa con el pedestal de Uldum en el Desierto de Tanaris." },
    [2962] = { "Necesitamos más material verdoso", "Viaja hasta Gnomeregan y recupera los restos radiactivos de gran potencia. Pero ten cuidado, ya que es inestable y podría explotar en cualquier momento.\n\nOzzie también quiere que traigas la ampolla pesada de plomo una vez que hayas terminado el trabajo.|n" },
    [2963] = { "Presagios de Uldum", "Habla con Karnik el Historiador en la Sala de los Expedicionarios de Forjaz." },
    [2964] = { "Una tarea futura", "Habla con el alto expedicionario Magellas de Forjaz." },
    [2965] = { "Presagios de Uldum", "Habla con Nara Ferocrín en el Alto de los Ancestros de Cima del Trueno." },
    [2966] = { "A ver qué pasa", "Lleva los discos de platino en miniatura a las puertas de Uldum, en Tanaris. Busca pistas sobre la conexión entre discos y puertas." },
    [2967] = { "Regresa a Cima del Trueno", "Habla con Nara Ferocrín en Cima del Trueno." },
    [2968] = { "Una tarea futura", "Habla con Sabio Buscador de la Verdad en Cima del Trueno." },
    [2977] = { "Regresa a Forjaz", "Habla con Karnik el Historiador de Forjaz." },
    [2988] = { "Las jaulas de Secacorteza", "Mira en las jaulas de los poblados Secacorteza y vuelve a ver al maestro de grifos Garracha." },
    [2989] = { "El Altar de Zul", "Mira en el Altar de Zul y vuelve a ver al maestro de grifos Garracha." },
    [2990] = { "Thadius Sombramacabra", "Lleva la pluma de Picoafilado a Thadius Sombramacabra a Las Tierras Devastadas." },
    [2991] = { "Medallón de Nekrum", "Lleva el medallón de Nekrum a Thadius Sombramacabra a Las Tierras Devastadas." },
    [2992] = { "El ritual de adivinación", "Espera a que Sombramacabra realice el ritual de adivinación." },
    [2993] = { "Regresa a las Tierras del Interior", "Habla con el maestro de grifos Garracha." },
    [2994] = { "Salvar a Picoafilado", "Llega hasta la cima de Jintha'Alor, mata a la sacerdotisa vil Hexx, consigue la llave de la jaula y rescata a Picoafilado." },
    [3042] = { "Temple trol", "Lleva 20 viales de temple trol a Trenton Mazaligera en Gadgetzan." },
    [3341] = { "Acaba con la amenaza", "Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su cráneo." },
    [3369] = { "En las pesadillas", "Lleva el Fragmento de Pesadilla a Hamuul Tótem de Runa en el Alto de los Ancestros." },
    [3370] = { "En las pesadillas", "Lleva el Fragmento de Pesadilla a Mathrengyl Garroso de Darnassus." },
    [3373] = { "La esencia de Eranikus", "Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido." },
    [3374] = { "La esencia de Eranikus", "Llévale la piedra de juramento del Vuelo de Ysera y la esencia encadenada de Eranikus a Itharius, que está en el Pantano de las Penas. Una vez allí, deberás decidir si quieres ayudar al Vuelo de Ysera o no." },
    [3375] = { "Otra ampolla", "Lleva 1 poción de maná, 1 trozo de carbón y néctar dulce a Talvash del Kissel a Forjaz. Te dará una ampolla de adivinación." },
    [3380] = { "El Templo Sumergido", "Encuentra a Marvon Buscarroblones en Tanaris." },
    [3441] = { "Castigo divino", "Escucha a Kalaran Espada del Viento." },
    [3442] = { "La llama pura", "Lleva 4 corazones de llama y 4 globos de aceite gólem a Kalaran Espada del Viento." },
    [3443] = { "Forjar el mango", "Lleva 8 dagas bañadas en torio a Kalaran Espada del Viento." },
    [3444] = { "El círculo de piedra", "Recupera el círculo de piedra del taller de Marvon Buscarroblones, en Trinquete." },
    [3445] = { "El Templo Sumergido", "Encuentra a Marvon Buscarroblones en Tanaris." },
    [3446] = { "En las profundidades", "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas." },
    [3447] = { "El secreto del círculo", "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas." },
    [3452] = { "El soporte para la llama", "Lleva un Símbolo de Ragnaros a Kalaran Espada del Viento." },
    [3453] = { "La antorcha de reprensión", "Espera a que Kalaran Espada del Viento termine la antorcha de reprensión.|n" },
    [3454] = { "La antorcha de reprensión", "Coge la antorcha de reprensión." },
    [3462] = { "Escudero Maltrake", "Habla con mi enviado, el escudero Maltrake." },
    [3463] = { "¡Préndeles fuego!", "Entra en las 4 torres del centinela e incéndialas con la antorcha de reprensión.|n" },
    [3481] = { "Abalorios...", "Abre el cofre." },
    [3512] = { "Como diría Eranikus...", "Viaja a la parte este de Cuna del Invierno y habla con Umbranse el Hablaalmas." },
    [3520] = { "Los espíritus de los estridadores", "Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor." },
    [3523] = { "La plaga de la Zahúrda", "Si decides ayudar a Belnistrasz, habla con él otra vez y devuélvele la piedra de juramento." },
    [3525] = { "Extinguir el ídolo", "Acompaña a Belnistrasz al ídolo jabaespín en Zahúrda Rajacieno. \n\nProtégelo mientras realiza el ritual para inutilizar el ídolo." },
    [3527] = { "La profecía de Mosh'aru", "Llévale la primera y segunda tablillas Mosh'aru a Yeh'kinya, que está en Tanaris." },
    [3528] = { "El dios Hakkar", "Llévale el huevo de Hakkar relleno a Yeh'kinya, que está en Tanaris." },
    [3636] = { "Trae la Luz", "El arzobispo Benedictus quiere que mates a Amnennar el Gélido en Zahúrda Rajacieno." },
    [3701] = { "Las humeantes Ruinas de Thaurissan", "Ve a las Ruinas de Thaurissan, en Las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa a la historiadora real Archesonus." },
    [3702] = { "Las humeantes Ruinas de Thaurissan", "Escucha a la historiadora real Archesonus relatar la historia de Thaurissan." },
    [3765] = { "Lejana corrupción", "Ve a ver a Gershala Susurro Nocturno en Auberdine." },
    [3801] = { "El legado de los Hierro Negro", "Habla con Franclorn Forjador en la Tumba de Forjador, en la Montaña Roca Negra, si te interesa obtener una llave de la ciudad." },
    [3802] = { "El legado de los Hierro Negro", "Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjador.|n" },
    [3906] = { "La discordia de las llamas", "Ve a la cantera de la Montaña Roca Negra y ejecuta al Maestro Supremo Pyron. Vuelve junto a Corazón Atronador cuando hayas completado este encargo.|n" },
    [3907] = { "La discordia del fuego", "Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Corazón Atronador.|n" },
    [3981] = { "Comandante Gor'shak", "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra.\n\nRecuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar." },
    [3982] = { "¿Qué pasa?", "Defiende a Gor'shak." },
    [4001] = { "¿Qué pasa?", "Habla con Kharan Martillo Poderoso y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar.\n\nRecuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana.|n" },
    [4002] = { "Los Reinos del Este", "Si aceptas la misión, habla con Thrall." },
    [4003] = { "El rescate real", "Mata al emperador Dagran Thaurissan para liberar a la princesa Moira Barbabronce del hechizo.|n" },
    [4004] = { "¿Princesa salvada?", "Vuelve junto a Thrall en el Fuerte Grommash en Orgrimmar.|n" },
    [4022] = { "Un sabor a llamarada", "Enséñale a Cyrus Therepentio la escama de Vuelo Negro que recibiste de Kalaran Espada del Viento.|n" },
    [4023] = { "Un sabor a llamarada", "Demuéstrale a Cyrus Therepentio lo que vales.\n\nTe da la impresión de que Cyrus ya sabe que no eres digno." },
    [4024] = { "Un sabor a llamarada", "Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar.\n\nSolo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia ígnea.\n\nLlévale la esencia ígnea encerrada a Cyrus Therepentio.|n" },
    [4061] = { "La revuelta de las máquinas", "Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos elementales fracturados para Hierofante Theodora Mulvadania.\n\nRecuerdas que Theodora mencionó que los gólems y elementales de esa región eran la fuente de estos fragmentos." },
    [4062] = { "La revuelta de las máquinas", "Lleva el ejemplar de fragmento elemental a Lotwil Veriatus.\n\nRecuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este.|n" },
    [4063] = { "La revuelta de las máquinas", "Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los gólems Furiatracadores y de los ensamblajes belisario que protegen a Argelmach. Lo sabes porque eres $gun adivino:una adivina;." },
    [4081] = { "MATAR INMEDIATAMENTE: enanos Hierro Negro", "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!\n\nEl señor de la guerra Dientegore quiere que mates a 15 celadores Yunque Colérico, 10 alcaides Yunque Colérico y 5 lacayos Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.|n" },
    [4082] = { "MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango", "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!\n\nEl señor de la guerra Dientegore quiere que mates a 10 médicos Yunque Colérico, 10 soldados Yunque Colérico y 10 oficiales Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea." },
    [4121] = { "¡Estás en un aprieto!", "Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego.\n\nRecuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.\n\nTambién tendrás que entregarle a Lexlort los grilletes de torio." },
    [4122] = { "Grark Lorkrub", "Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra.\n\nCuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.|n" },
    [4123] = { "El corazón de la montaña", "Llévale el corazón de la montaña a Maxwort Suprandor en Las Estepas Ardientes." },
    [4126] = { "Hurley Negrálito", "Llévale la receta de Cebatruenos perdida a Ragnar Cebatruenos en Kharanos." },
    [4132] = { "Operación: muerte a Forjainquina", "Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjainquina! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea." },
    [4134] = { "La receta de Cebatruenos perdida", "Llévale la receta de Cebatruenos perdida a Vivian Lagrave en Kargath." },
    [4136] = { "Ribbly Llavenrosca", "Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes." },
    [4141] = { "Muigin y Larion", "Recoge 15 pétalos de sangre y ve a ver a Muigin." },
    [4142] = { "Visita a Gregan", "Llévale un Sangrepétalo a Gregan Tirabirras de Feralas." },
    [4143] = { "Bruma del mal", "Reúne 5 muestras de calima Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro." },
    [4144] = { "Brotes Sangrepétalo" },
    [4145] = { "Larion y Muigin", "Caza 5 azotadores Sangrepétalo, 5 trilladores Sangrepétalo, 5 desolladores Sangrepétalo y 5 tramperos Sangrepétalo para Larion en el Refugio de Marshal." },
    [4146] = { "Combustible de irradior", "Entrega el Controlador descargado y 5 muestras de calima Atal'ai a Larion, en el Refugio de Marshal." },
    [4147] = { "El taller de Marvon", "Viaja hasta el taller de Marvon Buscarroblones en Trinquete." },
    [4148] = { "Liquidador de Sangrepétalo" },
    [4182] = { "La amenaza de los dragonantes", "Mata 15 estirpes negras, 10 dragauros negros, 4 vermintes negros y 1 draco negro." },
    [4183] = { "Los verdaderos maestros", "Viaja a Villa del Lago, en las Montañas Crestagrana, y entrégale la carta de Helendis Rivacuerno al magistrado Solomon." },
    [4184] = { "Los verdaderos maestros", "Ve a Ventormenta para entregar la petición de ayuda de Solomon al rey Varian Wrynn. \n\nVive en el Castillo de Ventormenta." },
    [4185] = { "Los verdaderos maestros", "Habla con el alto señor Bolvar Fordragón después de hablar con Lady Katrana Prestor." },
    [4186] = { "Los verdaderos maestros", "Lleva el decreto de Wrynn al magistrado Solomon en la Villa del Lago.|n" },
    [4201] = { "La poción de enamoramiento", "Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la coima Nagmara en las Profundidades de Roca Negra." },
    [4223] = { "Los verdaderos maestros", "Habla con el mariscal Maxwell en Las Estepas Ardientes." },
    [4224] = { "Los verdaderos maestros", "Habla con John Andrajoso." },
    [4241] = { "El mariscal Windsor", "Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al mariscal Windsor.\n\nRecuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor." },
    [4242] = { "Esperanza perdida", "Dale las malas noticias al mariscal Maxwell en la Vigilia de Morgan, en las Estepas Ardientes." },
    [4262] = { "Maestro supremo Pyron", "Mata al Maestro Supremo Pyron.\n\nRecuerdas que Jalinda dijo que Pyron guardaba la cantera. Quizás deberías empezar a buscar allí." },
    [4263] = { "¡Incendius!", "Encuentra a Lord Incendius en las Profundidades de Roca Negra ¡y acaba con él!" },
    [4264] = { "Una nota arrugada", "Puede que acabes de toparte con algo que le interesaría ver al mariscal Windsor. Puede que haya esperanza, después de todo." },
    [4282] = { "Una brizna de esperanza", "Devuélvele al mariscal Windsor la información perdida.\n\nEl mariscal Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjainquina." },
    [4286] = { "Buena mercancía", "Recupera 20 riñoneras Hierro Negro." },
    [4322] = { "La fuga de la prisión", "Ayuda al mariscal Windsor a recuperar su equipo y a liberar a sus amigos. Vuelve junto al mariscal Maxwell si lo consigues." },
    [4341] = { "Kharan Martillo Poderoso", "Ve a las Profundidades de Roca Negra y encuentra a Kharan Martillo Poderoso.\n\nEl rey dijo que estaba prisionero allí; busca una cárcel." },
    [4342] = { "El relato de Kharan", "Escucha la historia de Kharan Martillo Poderoso." },
    [4361] = { "Portador de malas noticias", "Regresa a Forjaz y dale las malas noticias al rey Magni Barbabronce." },
    [4362] = { "El destino del reino", "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan.|n" },
    [4363] = { "La sorpresa de la princesa", "Regresa a Forjaz y habla con el rey Magni Barbabronce." },
    [4601] = { "¡El Destellamatic 5200!", "Inserta un objeto con mugre incrustada en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano." },
    [4602] = { "¡El Destellamatic 5200!", "Inserta un objeto con mugre incrustada en el Destellamatic 5200 y asegúrate de tener tres monedas de plata a mano." },
    [4603] = { "El Destellamatic en acción" },
    [4604] = { "El Destellamatic en acción" },
    [4605] = { "¡El Destellamatic 5200!" },
    [4606] = { "¡El Destellamatic 5200!" },
    [4701] = { "Acaba con el origen de la amenaza", "Viaja hasta la Cumbre de Roca Negra y destruye el origen de la amenaza del huargo. Cuando dejaste a Helendis, gritó un nombre: Halycon. Es la palabra que los orcos usan para referirse al huargo." },
    [4724] = { "La maestra de la manada", "Mata a Halycon, la maestra de la manada de los huargos Hacha de Sangre." },
    [4726] = { "Esencia de cría", "Llévale 8 esencias de cría y el Draco-Incarcinatrix 900 a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes." },
    [4729] = { "Las mascotas exóticas de Kibler", "Viaja hasta la Cumbre de Roca Negra y encuentra cachorros de huargo Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 cachorro de huargo enjaulado." },
    [4734] = { "Un huevo congelado", "Usa el prototipo de ovosciloscopio sobre un huevo de El Grajero, en la Cumbre de Roca Negra." },
    [4735] = { "La colecta de huevos", "Llévale 8 huevos de dragón y el módulo colectrónico a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes." },
    [4742] = { "El sello de ascensión", "Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el sello de ascensión sin adornar a Vaelan.\n\nLos generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el alto señor Omokk de los Cumbrerroca y el señor supremo Vermiothalak de los Hacha de Sangre." },
    [4743] = { "El sello de ascensión", "Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad.\n\nEste es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!" },
    [4764] = { "El Broche de Equipasino", "Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes." },
    [4765] = { "Entrega a Bonacresta", "Llévale el cajón de Bonacresta al conde Remington Bonacresta en el Castillo de Ventormenta, en Ventormenta." },
    [4768] = { "La tablilla de Rocanegra", "Llévale la tablilla de Rocanegra a la maga oscura Vivian Lagrave en Kargath." },
    [4771] = { "Gambito del Alba", "Coloca el Gambito del Alba en la Sala de la Visión de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink." },
    [4787] = { "El huevo antiguo", "Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris." },
    [4788] = { "Las últimas tablillas", "Llévale la quinta y sexta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris." },
    [4808] = { "Felnok Acerovera", "Entrégale la carta de Tinkee a Felnok Acerovera en Vista Eterna, en Cuna del Invierno." },
    [4809] = { "Cuernos de Orvallo", "Reúne 8 cuernos de quimera del Orvallo." },
    [4810] = { "Regresa junto a Tinkee", "Llévale el paquete de Felnok a Tinkee Vaporio en el Peñasco Llamarada en Las Estepas Ardientes." },
    [4862] = { "Bestia amaestrada", "Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler.\n\nYo diría que se pueden encontrar estos huevos cerca de arañas.|n" },
    [4866] = { "La leche de la madre", "En el corazón de la Cumbre de Roca Negra encontrarás a la madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti." },
    [4867] = { "Urok Aullasino", "Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh." },
    [4903] = { "La orden del Señor de la Guerra", "Mata al alto señor Omokk, al maestro de guerra Voone y al señor supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión." },
    [4941] = { "La sabiduría de Eitrigg", "Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall.\n\nRecuerdas haber visto a Eitrigg en la Cámara de Thrall." },
    [4974] = { "¡Por la Horda!", "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar." },
    [4981] = { "La espía Bijou", "Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou." },
    [4982] = { "Las pertenencias de Bijou", "Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad.|n" },
    [4983] = { "El informe de reconocimiento de Bijou", "Llévale el informe de reconocimiento de Bijou al maestro mayor Lexlort en Kargath.|n" },
    [5001] = { "Las pertenencias de Bijou", "Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!|n" },
    [5002] = { "Un mensaje para Maxwell", "Viaja a Las Estepas Ardientes y dale la información sobre Bijou al mariscal Maxwell." },
    [5047] = { "¡Finkle Einhorn, a tu servicio!", "Habla con Malyfous Martilloscuro en Vista Eterna." },
    [5063] = { "Almete del Sabio Escarlata", "Para crear el Almete del Sabio Escarlata deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 5 costuras desgarradas de abominación; 8 cristales Arcanos; 5 hilos escarlata encantados.\n\nTambién tendrás que pagar 50 piezas de oro para la elaboración del almete." },
    [5065] = { "Las tablillas perdidas Mosh'aru", "Llévale la tercera y cuarta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris." },
    [5067] = { "Leotardos de Arcana", "Para crear los leotardos arcana deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 5 costuras desgarradas de abominación; 5 barras de arcanita; 5 líquidos de embalsamar de Murmuhielo.\n\nTambién tendrás que pagar 50 piezas de oro para la elaboración del almete." },
    [5068] = { "Coraza Sed de Sangre", "Para crear la coraza Sed de Sangre deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 10 costuras desgarradas de abominación; 5 barras de arcanita; 5 pieles de Sombra.\n\nTambién tendrás que pagar 50 piezas de oro para la elaboración del almete." },
    [5081] = { "La misión de Maxwell", "Viaja a la Cumbre de Roca Negra y acaba con el maestro de guerra Voone, el alto señor Omokk y el señor supremo Vermiothalak." },
    [5089] = { "Orden del general Drakkisath", "Llévale la orden del general Drakkisath al mariscal Maxwell en Las Estepas Ardientes." },
    [5102] = { "Muerte al general Drakkisath", "Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath." },
    [5122] = { "El medallón de Fe" },
    [5125] = { "La estimación de Aurius" },
    [5126] = { "La historia de Lorax", "Habla con Lorax. Escucha todo lo que tiene que decirte.|n" },
    [5127] = { "La forja demoníaca", "Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pica manchada de sangre sobre su cadáver. Cuando hayas absorbido su alma, la pica estará manchada de alma.\n\nTambién debes encontrar la coraza cubierta de runas sin forjar.\n\nLleva la pica manchada de alma y la coraza cubierta de runas sin forjar a Lorax en Cuna del Invierno." },
    [5160] = { "El Protectorado de la matrona", "Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee." },
    [5161] = { "La cólera del Vuelo Azul", "Habla con Haleh si quieres continuar." },
    [5162] = { "La cólera del Vuelo Azul", "Habla con Jeziba en las Tierras de la Peste. Vive en Andorhal." },
    [5164] = { "Catálogo del Díscolo", "Lee el Catálogo del Díscolo.|n" },
    [5166] = { "Coraza del Vuelo Cromático", "Para forjar la coraza del Vuelo Cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos:\n\n1 caparazón cromático.\n\n10 escamas cromáticas luminosas.\n\n10 sangres de héroes.\n\n10 costuras desgarradas de abominación." },
    [5167] = { "Quijotes del desafiante cromático", "Para forjar los quijotes del desafiante cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos:\n\n1 caparazón cromático.\n\n10 escamas cromáticas luminosas.\n\n10 sangres de héroes.\n\n5 pieles de Sombra." },
    [5212] = { "La carne no miente", "Recoge 10 muestras de carne apestada de Stratholme y vuelve con Betina Bigglezink. Sospechas que podrías obtener una muestra de cualquier criatura de Stratholme." },
    [5213] = { "El agente activo", "Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink.|n" },
    [5214] = { "El gran Fras Siabi", "Encuentra la Tienda de humo de Fras Siabi en Stratholme y recupera una caja del tabaco de calidad de Siabi. Cuando lo hayas hecho, vuelve con Smokey LaRue.|n" },
    [5243] = { "Las casas de lo sagrado", "Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido." },
    [5251] = { "El archivista", "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata." },
    [5262] = { "La verdad cae del cielo", "Lleva la cabeza de Balnazzar al duque Nicolas Zverenhoff en las Tierras de la Peste del Este." },
    [5263] = { "Por encima y más allá", "Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff.|n" },
    [5264] = { "Lord Maxwell Neófitus", "Habla con Lord Maxwell Neófitus. Está en el interior de la iglesia." },
    [5265] = { "El Bastión Argenta", "Abre el Bastión Argenta y reclama tu recompensa." },
    [5281] = { "Espíritus inquietos", "Encuentra a Egan. Solo sabes que fue visto por última vez en los alrededores de Stratholme." },
    [5282] = { "Espíritus inquietos", "Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre.\n\nLibera 15 almas y regresa a Egan." },
    [5341] = { "La fortuna de la familia Barov", "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea." },
    [5342] = { "El último de los Barov", "Viaja al Campamento del Orvallo, territorio de la Alianza, y asesina a Weldon Barov. Coge su cabeza y regresa con Alexi Barov.\n\nTen cuidado, Alexi seguramente estará muy protegido por la escoria de la Alianza." },
    [5343] = { "La fortuna de la familia Barov", "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras de Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea." },
    [5344] = { "El último de los Barov", "Viaja a El Baluarte, territorio de la Horda, y asesina a Alexi Barov. Coge su cabeza y regresa con Weldon Barov.\n\nTen cuidado, Alexi seguramente estará muy protegido por la escoria de la Horda." },
    [5382] = { "Doctor Theolen Krastinov, el Carnicero", "Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff.|n" },
    [5384] = { "Kirtonos el Heraldo", "Vuelve a Scholomance con la sangre inocente. Busca el Porche y coloca la Sangre de los inocentes en el blandón. Kirtonos acudirá a devorar tu alma.\n\nLucha con valentía, ¡no cedas ni una pulgada! Destruye a Kirtonos y vuelve con Eva Sarkhoff.|n" },
    [5461] = { "El humano, Ras Murmuhielo", "Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Libro de los Recuerdos. Si lo encuentras llévaselo al magistrado Marduke." },
    [5462] = { "El moribundo, Ras Murmuhielo", "Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Libro de los Recuerdos y cuéntale todo lo que has descubierto." },
    [5463] = { "El Obsequio de Menethil", "Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Libro de los Recuerdos en suelo no consagrado." },
    [5464] = { "El Obsequio de Menethil", "Lleva el Libro de Memorias del Alma a Leonid Barthalomew a las Tierras de la Peste del Este." },
    [5465] = { "El Libro de Memorias del Alma", "Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale el Libro de Memorias del Alma." },
    [5466] = { "El exánime, Ras Murmuhielo", "Busca a Ras Murmuhielo en Scholomance. Cuando lo hayas encontrado utiliza el Libro de Memorias del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Murmuhielo. Lleva la cabeza al magistrado Marduke." },
    [5515] = { "Bolsa de los horrores de Krastinov", "Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff." },
    [5518] = { "El disfraz de ogro Gordok", "Lleva 4 madejas de paño rúnico, 8 cueros bastos, 2 hilos rúnicos y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre." },
    [5519] = { "El disfraz de ogro Gordok" },
    [5522] = { "Leonid Barthalomew", "Lleva los huevos congelados a Leonid Barthalomew a las Tierras de la Peste del Este." },
    [5525] = { "¡Libera a Knot!" },
    [5526] = { "Fragmentos de gangrevid", "Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de Pureza para guardar el fragmento y llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna." },
    [5527] = { "Un relicario de Pureza", "Ve a Silithus a buscar un relicario de Pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna." },
    [5528] = { "La cata de los Gordok" },
    [5529] = { "Crías de dragón apestadas", "Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz." },
    [5531] = { "Betina Bigglezink", "Lleva los huevos congelados a Betina Bigglezink." },
    [5542] = { "Perros demoníacos", "Mata 20 cachorros de can de peste, 5 canes de peste y 5 canes de peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín." },
    [5543] = { "Cielos sangrientos", "Mata 30 murcipestes y vuelve con Tirion Vadín." },
    [5544] = { "Gusanos carroñeros", "Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero.|n" },
    [5582] = { "Escama de dragón sana", "Lleva la escama de dragón sana a Betina Bigglezink a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este." },
    [5722] = { "Buscando la cartera perdida", "Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés." },
    [5723] = { "Midiendo fuerzas con el enemigo", "Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno." },
    [5724] = { "La vuelta de la cartera perdida", "Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno." },
    [5725] = { "Poder destructivo", "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas." },
    [5726] = { "Enemigos ocultos", "Lleva una insignia de Teniente a Thrall a Orgrimmar." },
    [5727] = { "Enemigos ocultos", "Lleva la insignia de Teniente a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar." },
    [5728] = { "Enemigos ocultos", "Mata a Bazzalan y a Jergosh el Convocador y ve a ver a Thrall a Orgrimmar." },
    [5729] = { "Enemigos ocultos", "Habla con Neeru Hojafuego en Orgrimmar." },
    [5730] = { "Enemigos ocultos", "Habla con Thrall en Orgrimmar y cuéntale lo que has averiguado." },
    [5742] = { "Redención", "Escucha lo que Tirion Vadín tiene que contarte." },
    [5761] = { "Matar a la bestia", "Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar." },
    [5781] = { "De recuerdos olvidados", "Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín." },
    [5845] = { "Del honor perdido", "Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo de Honor perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Vadín." },
    [5846] = { "Del amor y la familia", "Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro." },
    [5848] = { "Del amor y la familia", "Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'Del amor y la familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo.\n\nDevuelve la pintura a Tirion Vadín." },
    [5861] = { "Encuentra a Myranda", "Viaja a la Tumba de Uther, en el sur de las Tierras de la Peste. Enseña a Myranda la Fada el obsequio de Tirion." },
    [5862] = { "El subterfugio Escarlata", "Habla con Myranda para conseguir la Ilusión Escarlata. Bajo el poder de la Ilusión Escarlata viaja a la Vega del Amparo y entrega el obsequio de Tirion al alto señor Taelan Vadín.\n\nLa Vega del Amparo está al Norte, Taelan seguramente estará en el interior de la Fortaleza de Mardenholde." },
    [5944] = { "En sueños", "Escolta a Taelan Vadín fuera de la Vega del Amparo." },
    [6022] = { "Matar con un propósito", "Viaja al Cruce de Corin al este y mata a los miembros de la Plaga que habitan allí. Recoge 7 piezas de putrefacción viva en 10 minutos. Utiliza el mortero y el majadero para convertir la putrefacción viva en putrefacción coagulada." },
    [6042] = { "Los pequeños problemas de la no-vida", "Mata a 20 murcipestes tóxicos y 10 murcipestes monstruosos. Vuelve con Nathanos Clamañublo cuando hayas acabado." },
    [6133] = { "La orden del Señor forestal", "Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien.\n\nTambién tienes que matar a 8 forestales, 8 zancaminos y 8 leñadores." },
    [6135] = { "Alaocaso, cómo te odio...", "Encuentra a Alaocaso y mátalo. Recoge un parche de pelaje de Alaocaso de su cadáver y llévaselo a Nathanos Clamañublo.\n\nSe dice que Alaocaso vaga por el campo, al norte de la Hacienda de Marris." },
    [6136] = { "El corpulento", "Encuentra a Borelgore en las planicies del norte de las Tierras de la Peste del Este y destrúyelo. Vuelve junto a Nathanos Clamañublo cuando hayas cumplido la misión." },
    [6163] = { "Ramstein", "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos." },
    [6402] = { "Tienes una cita en Ventormenta", "Viaja hasta la Ciudad de Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al mariscal Windsor sobre tu llegada." },
    [6403] = { "La gran farsa", "Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!" },
    [6501] = { "El Ojo del Dragón", "Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del Dragón. La única información que tienes sobre dicho ser es que existe." },
    [6502] = { "Amuleto Pirodraco", "Tienes que recuperar la sangre de dragón Negro Campeón, la tiene el general Drakkisath. Puedes encontrar a Drakkisath en su sala del trono, tras las Salas de la Ascensión, en la Cumbre de Roca Negra." },
    [6521] = { "Una alianza impía", "Lleva la cabeza del embajador Malcin a Bragor Puñosangre, que está en Entrañas." },
    [6522] = { "Una alianza impía", "Lleva el pergamino pequeño a Bragor Puñosangre que está en el Barrio Real en Entrañas." },
    [6561] = { "La vileza de Brazanegra", "Llévale la cabeza del señor crepuscular Kelris a Bashana Tótem de Runa en Cima del Trueno." },
    [6562] = { "Problemas en las profundidades", "Habla con Je'neu Sancrea en Vallefresno." },
    [6563] = { "La esencia de Aku'Mai", "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno." },
    [6564] = { "Lealtad a los dioses antiguos", "Llévale la nota mojada a Je'neu Sancrea en Vallefresno." },
    [6565] = { "Lealtad a los dioses antiguos", "Mata a Lorgus Jett." },
    [6566] = { "Lo que trae el viento", "Escucha a Thrall." },
    [6567] = { "El Campeón de la Horda", "Busca a Rokaro en la Aldea Cazasombras, en Desolace." },
    [6568] = { "Profesora del engaño", "Entrega la carta de Rokaro a Myranda la Fada en las Tierras de la Peste del Oeste." },
    [6569] = { "Ilusiones oculares", "Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada." },
    [6570] = { "Brasaliza", "Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca El Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza.|n" },
    [6582] = { "La prueba de los cráneos, Arúspice", "Debes encontrar a Arúspice, el Campeón draco del Vuelo Azul y matarlo. Separa su cráneo de su cuerpo y llévaselo a Brasaliza.\n\nSabes que puedes encontrar a Arúspice en Cuna del Invierno." },
    [6583] = { "La prueba de los cráneos, Somnus", "Destruye al Campeón del Vuelo Verde, Somnus. Lleva su cráneo a Brasaliza." },
    [6584] = { "La prueba de los cráneos, Chronalis", "Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su cráneo a Brasaliza." },
    [6585] = { "La prueba de los cráneos, Axtroz", "Viaja a Grim Batol y encuentra a Axtroz, el Campeón del Vuelo Rojo. Destrúyelo y hazte con su cráneo. Llévaselo a Brasaliza." },
    [6601] = { "El ascenso", "Diría que se acabaron las charadas. Ya sabes que el amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en el interior de la Cumbre de Roca Negra. Quizás deberías buscar a Rokaro y explicarle el apuro en el que te encuentras. Enséñale el amuleto Pirodraco apagado. Con un poco de suerte, él sabrá que hay que hacer ahora." },
    [6602] = { "La sangre de dragón Negro Campeón", "Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y llévasela a Rokaro." },
    [6626] = { "Un anfitrión del mal", "Mata a 8 guardias de batalla de Rajacieno y 8 tejespinas Rajacieno y 8 cultores Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno." },
    [6627] = { "Prueba de conocimiento", "Responde la pregunta de Braug Espíritu Tenue con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés $glisto:lista;." },
    [6628] = { "Prueba de conocimiento", "Responde la pregunta de Parqual Fintallas con acierto y después habla con él de nuevo. Se quedará en Entrañas hasta que estés $glisto:lista;." },
    [6804] = { "Agua envenenada", "Aplica el aspecto de Neptulon a los elementales infectados de las Tierras de la Peste del Este. Lleva 12 de sus brazales discordantes y el aspecto de Neptulon al duque Hydraxis a Azshara." },
    [6805] = { "Sirocosos y reptarenas", "Acaba con 15 agitadores sirocosos y 15 estruendores del desierto. Después, regresa con el duque Hydraxis en Azshara." },
    [6821] = { "Ojo del Brasadivino", "Lleva el ojo del Brasadivino al duque Hydraxis a Azshara." },
    [6822] = { "El Núcleo de Magma", "Mata a 1 señor del Fuego, 1 gigante fundido, 1 can del Núcleo anciano y 1 marea de lava y ve a ver al duque Hydraxis a Azshara." },
    [6823] = { "Agente de Hydraxis", "Consigue una mención de honor de los Señores del Agua y habla con el duque Hydraxis en Azshara." },
    [6824] = { "Las manos de los enemigos", "Lleva las manos de Lucifron, Sulfuron, Gehennas y Shazzrah al duque Hydraxis a Azshara." },
    [6921] = { "Entre ruinas", "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno." },
    [6922] = { "Barón Aquanis", "Llévale el extraño globo de agua a Je'neu Sancrea en las Cavernas de Brazanegra." },
    [6981] = { "El fragmento resplandeciente", "Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento resplandeciente.\n\nEntrega el fragmento como se te indique." },
    [7028] = { "Los males de Maraudon", "Recoge 15 tallas de cristal terádrico y llévaselas a Willow a Desolace." },
    [7029] = { "La corrupción de Lenguavil", "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon. \n\nAplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico. \n\nCura 8 plantas eliminando su sucesor tóxico e informa a Vark Marca de Guerra en la Aldea Cazasombras." },
    [7041] = { "La corrupción de Lenguavil", "Llena el vial cerúleo cubierto en el estanque naranja de Maraudon. \n\nAplica el vial cerúleo lleno a la hiedravil para que emerja el sucesor tóxico. \n\nCura 8 plantas eliminando su sucesor tóxico e informa a Talendria en Punta de Nijel." },
    [7044] = { "Leyendas de Maraudon", "Recupera las 2 partes del cetro de Celebras: la vara y el diamante de Celebras. \n\nEncuentra el modo de hablar con Celebras." },
    [7046] = { "El cetro de Celebras", "Ayuda a Celebras el Redimido mientras reconstruye el cetro de Celebras. \n\nHabla con él después del ritual." },
    [7064] = { "Corrupción de la tierra y de la semilla", "Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace." },
    [7065] = { "Corrupción de la tierra y de la semilla", "Mata a la princesa Theradras y ve a ver al vigilante Marandis a Punta de Nijel, en Desolace." },
    [7066] = { "La semilla de vida", "Busca a Remulos en Claro de la Luna y dale la semilla de vida." },
    [7067] = { "Las instrucciones del Paria", "Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace." },
    [7068] = { "Trozos Oscuros", "Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar." },
    [7070] = { "Trozos Oscuros", "Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango." },
    [7201] = { "El último elemento", "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los gólems y a los creadores de gólems. Recuerdas que Vivian Lagrave también murmuró entre dientes algo sobre los elementales.|n" },
    [7429] = { "¡Libera a Knot!" },
    [7441] = { "Pusillín y el ancestro Azj'Tordin", "Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de Conjuros de Azj'Tordin, por cualquier medio. \n\nSi consigues hacerte con el libro de Conjuros, vuelve al Pabellón de Lariss de Feralas y busca a Azj'Tordin." },
    [7461] = { "Locura interior", "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará. \n\nEntra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum. \n\nSi consigues completar esta misión, ve al patio a buscar a la ancestro Shen'dralar." },
    [7462] = { "El tesoro de los Shen'dralar", "Vuelve a El Athenaeum y encuentra el tesoro de los Shen'dralar. ¡Reclama tu recompensa!" },
    [7463] = { "El refresco arcano", "Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al Tradicionalista Lydros que está en El Athenaeum." },
    [7481] = { "Leyendas élficas", "Busca a Kariel Winthalus en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres." },
    [7482] = { "Leyendas élficas", "Busca a Kariel Winthalus en La Masacre. Vuelve al Bastión Plumaluna a informar al erudita Runaespina de lo que hayas encontrado." },
    [7483] = { "El tratado sobre rapidez", "Lleva 1 tratado sobre rapidez, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 2 sangres de héroes al Tradicionalista Lydros a La Masacre para conseguir un arcanum de rapidez." },
    [7484] = { "El tratado sobre enfoque", "Lleva 1 tratado sobre enfoque, 1 diamante negro prístino, 4 fragmentos luminosos grandes y 2 pieles de Sombra al Tradicionalista Lydros a La Masacre para conseguir un arcanum de enfoque." },
    [7485] = { "El tratado sobre protección", "Lleva 1 tratado sobre protección, 1 diamante negro prístino, 2 fragmentos luminosos grandes y 1 costura desgarrada de abominación al Tradicionalista Lydros a La Masacre para conseguir un arcanum de protección." },
    [7486] = { "Una recompensa de héroe", "Recoge tu recompensa en el arca de Hydraxis." },
    [7488] = { "La membrana de Lethtendris", "Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas." },
    [7489] = { "La membrana de Lethtendris", "Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas." },
    [7490] = { "Victoria para la Horda", "Lleva la cabeza de Onyxia a Garrosh a Orgrimmar." },
    [7491] = { "Para que todos lo vean", "Busca al señor supremo Runthak en el Valle de la Fuerza." },
    [7493] = { "El viaje acaba de empezar" },
    [7495] = { "Victoria para la Alianza", "Lleva la cabeza de Onyxia al rey Varian Wrynn en Ventormenta." },
    [7496] = { "Celebrar los buenos momentos", "Busca al mayor Mattingly en el Valle de los Héroes." },
    [7497] = { "El viaje acaba de empezar" },
    [7503] = { "La mejor raza de cazadores", "Devuelve el libro a sus legítimos dueños." },
    [7507] = { "Compendio de Foror", "Devuelve el compendio de matar dragones de Foror a El Athenaeum." },
    [7508] = { "Forjar Quel'Serrar", "Entrega la hoja élfica roma Tradicionalista Lydros." },
    [7509] = { "Forjar Quel'Serrar", "Debes conseguir que Onyxia escupa fuego sobre la hoja antigua sin templar. Una vez hecho, recógela, su hoja estará candente. Pero ten cuidado: una hoja candente no permanecerá así para siempre, no tienes tiempo que perder. \n\nAntes de volver a mí, tienes que terminar lo empezado, debes matar a la bestia e introducir la hoja candente en su cadáver. \n\nHazlo y Quel'Serrar será tuya." },
    [7562] = { "Mor'zul Sangredoble", "Habla con Mor'zul Sangredoble en el Altar de la Tempestad en Las Estepas Ardientes." },
    [7563] = { "La ira de sangre", "Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes." },
    [7564] = { "Ojovago", "Llévale el estuche de sangre a Gorzeeki Ojovago al Altar de la Tempestad, en Las Estepas Ardientes." },
    [7629] = { "Entrega de diablillo", "Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el papiro llévale el tarro a Gorzeeki Ojovago." },
    [7637] = { "Énfasis en el sacrificio", "Viaja a Forjaz y consigue el incensario de exorcismos del sumo sacerdote Rohan. Tendrás que hacer una donación de 150 monedas de oro para conseguirlo." },
    [7638] = { "Lord Grisillo Quiebrasombras", "Habla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7639] = { "Mostrarse juicioso", "Devuelve el incensario de exorcismos a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7640] = { "Exorcismo en Valle del Terror", "Utiliza el incensario de exorcismos para expulsar los espíritus que atormentan el Valle del Terror. Cuando hayas matado 25 espíritus del Valle del Terror, vuelve a ver a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7641] = { "El trabajo de Grimand Elmore", "Habla con Grimand Elmore en el Distrito de los Enanos, en Ventormenta." },
    [7642] = { "Recopilación de artículos", "Lleva 40 paños rúnicos, 6 barras de arcanita, 10 lágrimas de Arthas, 5 viales de agua sagrada de Stratholme y 150 monedas de oro a Grimand Elmore en el Distrito de los Enanos de Ventormenta." },
    [7643] = { "El antiguo espíritu equino", "Consigue comida para caballos para alimentar a un espíritu equino. Por lo visto, Merideth Carlson, en Costasur, tiene esa comida.\n\nVe a la mazmorra de La Masacre, en Feralas y mata a Tendris Alabeo. Al hacerlo, liberarás al antiguo espíritu equino. Dale la comida para caballos y lo aplacarás. Por último, dale la gualdrapa de arcanita para que la bendiga." },
    [7644] = { "La gualdrapa de arcanita bendita", "Devuelve la gualdrapa de arcanita bendita a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7646] = { "El cristal de adivinación", "Lleva un diamante de Azeroth y un diamante negro prístino a Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta." },
    [7667] = { "Asistencia material", "Si te interesa ayudar a Sagorne Montacresta, llévale 1 diamante de Azeroth y 1 diamante negro prístino al Valle de la Sabiduría, en Orgrimmar." },
    [7668] = { "La amenaza de Atracoscuro", "Usa el cristal de adivinación en el corazón del sótano de El Gran Osario en Scholomance. Al hacerlo se presentarán los espíritus a los que tienes que enfrentarte. La derrota de estos espíritus invoca al caballero de la Muerte Atracoscuro, derrótalo.\n\nLlévale la cabeza de Atracoscuro a Sagorne Zanca Cresta en el Valle de la Sabiduría, en Orgrimmar." },
    [7669] = { "El regreso a El Gran Osario" },
    [7761] = { "Orden de Puño Negro", "¡Será estúpido ese orco! Al parecer, tienes que encontrar la enseña y ganar la marca de Drakkisath para poder acceder al orbe de orden.\n\nSegún la carta, el general Drakkisath guarda la enseña. Quizás deberías investigarlo." },
    [7848] = { "Armonización con el Núcleo", "Acércate al portal de entrada del Núcleo de Magma en las Profundidades de Roca Negra y recoge un trozo del Núcleo. Llévaselo a Lothos Levantagrietas a la Montaña Roca Negra." },
    [7877] = { "El tesoro de los Shen'dralar", "Vuelve a El Athenaeum y encuentra el tesoro de los Shen'dralar. ¡Reclama tu recompensa!" },
    [8181] = { "La confrontación con Yeh'kinya", "Habla con Yeh'kinya." },
    [8182] = { "La mano de Rastakhan", "Habla con Molthor en Tuercespina." },
    [8905] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales Corazón Salvaje a Deliana a Forjaz." },
    [8906] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 juego de ataduras de acechabestias a Deliana a Forjaz." },
    [8907] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 juego de ataduras de magister a Deliana a Forjaz." },
    [8908] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales Forjaluz a Deliana a Forjaz." },
    [8909] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales de devoto a Deliana a Forjaz." },
    [8910] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales arte sombrío a Deliana a Forjaz.|n" },
    [8911] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales calígine a Deliana a Forjaz.|n" },
    [8912] = { "Una propuesta seria", "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales de valor a Deliana a Forjaz." },
    [8913] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales Corazón Salvaje a Mokvar a Orgrimmar." },
    [8914] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 juego de ataduras de acechabestias a Mokvar a Orgrimmar." },
    [8915] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 juego de ataduras de magister a Mokvar a Orgrimmar.|n" },
    [8916] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales de devoto a Mokvar a Orgrimmar.|n" },
    [8917] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales arte sombrío a Mokvar a Orgrimmar.|n" },
    [8918] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de ataduras de elementos a Mokvar a Orgrimmar.|n" },
    [8919] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales calígine a Mokvar a Orgrimmar." },
    [8920] = { "Una propuesta seria", "Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales de valor a Mokvar a Orgrimmar.|n" },
    [8921] = { "El destilador ectoplásmico", "Vuelve a ver a Mux Cazamaná a Gadgetzan cuando tengas 1 conversor de arcanita delicado, 4 esencias eternas superiores, 10 unidades de aceite de escama pétrea, 25 cenizas volcánicas y 40 piezas de oro." },
    [8922] = { "Un artefacto sobrenatural", "Lleva el frasco de sangre sellado a Mux Cazamaná a Gadgetzan, en Tanaris." },
    [8923] = { "Un artefacto sobrenatural", "Lleva el frasco de veneno sellado a Mux Cazamaná a Gadgetzan." },
    [8924] = { "Caza de ectoplasmas", "Utiliza el destilador ectoplásmico cerca de los no-muertos incorpóreos y consigue 12 ectoplasmas agostados en Silithus, 12 ectoplasmas helados en Cuna del Invierno y 12 ectoplasmas estables en las Tierras de la Peste del Este. Llévaselos, junto con el destilador ectoplásmico, a Mux Cazamaná a Gadgetzan." },
    [8925] = { "Fuente de energía portátil", "Encuentra al Señor del Magma Bokk en Las Estepas Ardientes, consigue el núcleo de arrabio y llévaselo a Mux Cazamaná a Gadgetzan." },
    [8926] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes Corazón Salvaje a Deliana a Forjaz." },
    [8927] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes Corazón Salvaje a Mokvar a Orgrimmar." },
    [8928] = { "Un mercader sospechoso", "Busca a un diablillo dentro de una cueva situada a la entrada de la Garganta Negro Rumor en la zona sur de Cuna del Invierno, compra una biela de energía vil elemental y vuelve a ver a Mux Cazamaná a Gadgetzan." },
    [8929] = { "Buscando a Anthion", "Usa el detector de fantasmas extradimensional en la entrada de Stratholme y habla con el fantasma de Anthion Harmon." },
    [8930] = { "Buscando a Anthion", "Usa el detector de fantasmas extradimensional en la entrada de Stratholme y habla con el fantasma de Anthion Harmon." },
    [8931] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes de acechabestias a Deliana a Forjaz." },
    [8932] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes de magister a Deliana a Forjaz.|n" },
    [8933] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guanteletes Forjaluz a Deliana a Forjaz.|n" },
    [8934] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes de devoto a Deliana a Forjaz." },
    [8935] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes arte sombrío a Deliana a Forjaz." },
    [8936] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes calígine a Deliana a Forjaz." },
    [8937] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guanteletes de valor a Deliana a Forjaz." },
    [8938] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes de acechabestias a Mokvar a Orgrimmar." },
    [8939] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes de magister a Mokvar a Orgrimmar." },
    [8940] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes de devoto a Mokvar a Orgrimmar." },
    [8941] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes arte sombrío a Mokvar a Orgrimmar." },
    [8942] = { "Una compensación justa", "Lleva 1 cordón y 1 par de guanteletes de elementos a Mokvar a Orgrimmar.|n" },
    [8943] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guantes calígine a Mokvar a Orgrimmar.|n" },
    [8944] = { "Una compensación justa", "Lleva 1 cinturón y 1 par de guanteletes de valor a Mokvar a Orgrimmar.|n" },
    [8945] = { "La súplica de un muerto", "Ve a Stratholme y rescata a Ysida Harmon del Barón Osahendido." },
    [8946] = { "Prueba de vida", "Lleva el Guardapelo de Ysida a Anthion Harmon a las Tierras de la Peste del Este." },
    [8947] = { "La extraña petición de Anthion", "Lleva 3 barras de hierro negro, 20 retales de cuero encantado, 3 de tela lunar y 4 pellejos bastos curtidos a Anthion Harmon a las Tierras de la Peste del Este." },
    [8948] = { "Un viejo amigo de Anthion", "Lleva el estandarte de Provocación incompleto a Falrin Tallarbol que está en la biblioteca de La Masacre." },
    [8949] = { "La vendetta de Falrin", "Reúne 25 abalorios de guerra de ogro de los ogros de La Masacre o de la Cumbre de Roca Negra y vuelve a El Athenaeum de La Masacre a hablar con Falrin Tallarbol." },
    [8950] = { "El encantamiento del provocador", "Lleva a Falrin Tallarbol a La Masacre, lo siguiente: 1 esencia de espectro bufón, 4 runas oscuras y 8 fragmentos luminosos grandes." },
    [8951] = { "La despedida de Anthion", "Lleva 1 par de botas, 1 falda y 1 par de bufas Corazón Salvaje a Deliana a Forjaz." },
    [8952] = { "La despedida de Anthion", "Lleva 1 par de botas, 1 pantalón y 1 manto de acechabestias a Deliana a Forjaz." },
    [8953] = { "La despedida de Anthion", "Lleva 1 par de botas, 1 manto y 1 par de leotardos de magister a Deliana a Forjaz." },
    [8954] = { "La despedida de Anthion", "Lleva 1 par de botas, 1 par de quijotes y 1 par de bufas Forjaluz a Deliana a Forjaz." },
    [8955] = { "La despedida de Anthion", "Lleva 1 par de zapatos, 1 saya y 1 manto de devoto a Deliana a Forjaz." },
    [8956] = { "La despedida de Anthion", "Lleva 1 par de botas, 1 pantalón y 1 par de bufas arte sombrío a Deliana a Forjaz." },
    [8957] = { "La despedida de Anthion", "Lleva 1 par de botas, 1 falda y unos espaldares de elementos a Mokvar a Orgrimmar." },
    [8958] = { "La despedida de Anthion", "Lleva 1 par de sandalias, 1 par de leotardos y 1 manto calígine a Deliana a Forjaz." },
    [8959] = { "La despedida de Anthion", "Lleva 1 par de botas, 1 par de quijotes y 1 par de bufas de valor a Deliana a Forjaz." },
    [8960] = { "El triste destino de Bodley", "Viaja hasta la Montaña Roca Negra y usa el detector de fantasmas extradimensionales para encontrar a Bodley cerca de la Cumbre de Roca Negra." },
    [8961] = { "Tres reyes de Fuego", "Recolecta la incendicita de Incendius, el ascua del Brasadivino y el rescoldo de las brasas junto con el blandón sagrado y llévaselos a Bodley en el interior de la Montaña Roca Negra." },
    [8962] = { "Componentes importantes", "Consigue restos de druida y llévaselos a Bodley en el interior de la Montaña Roca Negra." },
    [8963] = { "Componentes importantes", "Consigue una reliquia de la Aldea Brisa Estelar y llévasela a Bodley en el interior de la Montaña Roca Negra." },
    [8964] = { "Componentes importantes", "Consigue una espada luminosa de zelote y llévasela a Bodley en el interior de la Montaña Roca Negra." },
    [8965] = { "Componentes importantes", "Consigue cenizas de almas de los Desterrados y llévaselas a Bodley en el interior de la Montaña Roca Negra." },
    [8966] = { "La parte izquierda del amuleto de Lord Valthalak", "Usa el Blandón de Señalización para invocar al espíritu de Mor Pezuña Gris y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización." },
    [8967] = { "La parte izquierda del amuleto de Lord Valthalak", "Usa el Blandón de Señalización para invocar al espíritu de Isalien y mátala. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización." },
    [8968] = { "La parte izquierda del amuleto de Lord Valthalak", "Usa el Blandón de Señalización para invocar al espíritu de Jarien y Sothos y mátalos. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización." },
